255		private List<DecoderCandidate> findDecoderCandidates() {
256			List<DecoderCandidate> candidates = new ArrayList<>();
257			FunctionManager functionManager = program.getFunctionManager();
258			FunctionIterator functions = functionManager.getFunctions(true);
259			while (functions.hasNext() && !monitor.isCancelled()) {
260				Function function = functions.next();
261				if (function.isExternal() || function.isThunk()) {
262					continue;
263				}
264				DecoderProfile profile = profile(function);
265				if (profile.score >= 4) {
266					candidates.add(
267						new DecoderCandidate(function, profile.operations, profile.score));
268				}
269			}
270	
271			candidates.sort(Comparator.comparingInt(DecoderCandidate::score)
272					.reversed()
273					.thenComparing(candidate -> candidate.function().getEntryPoint()));
274			if (candidates.size() > config.maxDecoders) {
275				return List.copyOf(candidates.subList(0, config.maxDecoders));
276			}
277			return List.copyOf(candidates);
278		}
