   179		private static byte[] encode(Sample sample) {
   180			byte[] data = sample.text().getBytes(StandardCharsets.US_ASCII);
   181			byte[] key = sample.key();
   182			List<Step> steps = sample.steps();
   183			for (int i = steps.size() - 1; i >= 0; i--) {
   184				Step step = steps.get(i);
   185				switch (step.operation()) {
   186					case XOR -> xor(data, key);
   187					case ADD -> add(data, key, -1);
   188					case SUB -> add(data, key, 1);
   189					case ROL -> rotate(data, step.amount(), false);
   190					case ROR -> rotate(data, step.amount(), true);
   191					case NOT -> {
   192						for (int j = 0; j < data.length; j++) {
   193							data[j] = (byte) ~data[j];
   194						}
   195					}
   196					case REVERSE -> reverse(data);
   197				}
   198			}
   199			return data;
   200		}
